<script setup lang="ts">
// the face and dress of a figure
import { computed } from 'vue'
import { race } from '../rules/races'
import type { Looks } from '../rules/hero'
const p = defineProps<{ l: Looks; race: string }>(); const R = computed(() => race(p.race)); const hairless = computed(() => !R.value.hairs.length)
const DYES = ['#7a2a2a', '#8a5a2a', '#b08a3a', '#4a5a2a', '#2a5a4a', '#2a4a7a', '#3d5aa0', '#4a2a6a', '#7a2a5a', '#2a2a30', '#6a6a70', '#d8d0b8'], EYES = ['#5a3a1a', '#4a6a7a', '#3a7a4a', '#7a7a3a', '#8a2a2a', '#6a4a9a']; const HAIRS: Record<string, string[]> = { m: ['Short', 'Long and bearded', 'Tied back', 'Mohawk', 'Bald and bearded'], f: ['Long', 'Pinned up', 'Bobbed', 'Braided', 'Cropped'] }
</script>
<template><div class="lk"><span class="lab">Build</span><div class="chips"><button class="chip" :class="{ on: l.sex === 'm' }" @click="l.sex = 'm'">Man</button><button class="chip" :class="{ on: l.sex === 'f' }" @click="l.sex = 'f'">Woman</button></div><span class="lab">{{ hairless ? 'Scales' : 'Skin' }}</span><div class="sw"><button v-for="c in R.skins" :key="c" :class="{ on: l.skin === c }" :style="{ background: c }" :aria-label="'Skin ' + c" @click="l.skin = c" /></div><template v-if="!hairless"><span class="lab">Hair</span><div class="chips"><button v-for="(h, i) in HAIRS[l.sex]" :key="h" class="chip s" :class="{ on: l.head === i }" @click="l.head = i">{{ h }}</button></div><div class="sw" style="margin-top:8px"><button v-for="c in R.hairs" :key="c" :class="{ on: l.hair === c }" :style="{ background: c }" :aria-label="'Hair ' + c" @click="l.hair = c" /></div><span class="lab">Eyes</span><div class="sw"><button v-for="c in EYES" :key="c" :class="{ on: l.eyes === c }" :style="{ background: c }" :aria-label="'Eyes ' + c" @click="l.eyes = c" /></div></template><span class="lab">Colours</span><div class="sw"><button v-for="c in DYES" :key="c" :class="{ on: l.cloth === c }" :style="{ background: c }" :aria-label="'Cloth ' + c" @click="l.cloth = c" /></div><div class="sw" style="margin-top:6px"><button v-for="c in DYES" :key="c" :class="{ on: l.trim === c }" :style="{ background: c }" :aria-label="'Trim ' + c" @click="l.trim = c" /></div><button class="opt" style="max-width:340px;margin-top:10px" :class="{ on: l.gear !== false }" @click="l.gear = l.gear === false"><i class="tick" /><span>Wear the hat, hood or helm</span></button></div></template>
<style scoped>.sw{display:flex;flex-wrap:wrap;gap:4px}.sw button{width:34px;height:30px}.sw button.on{outline:3px solid var(--ink);outline-offset:2px}</style>
